import { PAGES } from "@/config/pages-class.config";
import Link from "next/link";
import { usePathname } from "next/navigation";

const MENU_LINKS = [
  { label: "catalog", href: PAGES.CATALOG },
  { label: "cart", href: PAGES.CART },
  { label: "profile", href: PAGES.PROFILE },
];

export default function Menu() {
  const pathname = usePathname();

  return (
    <nav className="flex">
      <ul className="flex flex-row gap-2 dark:text-primary-text text-light-accent font-semibold text-sm font-secondary">
        {MENU_LINKS.map((link) => (
          <li className="flex" key={link.label}>
            <Link
              href={link.href}
              className={`pathname === link.label ? "text-white":"text-red" flex items-center w-full h-full px-4 uppercase hover:bg-border-gray/20 hover:text-brand-accent-dark transition delay-100 duration-200 ease-in cursor-pointer`}
            >
              {link.label}
            </Link>
          </li>
        ))}
      </ul>
    </nav>
  );
}
